import { PrismaClient } from "@/app/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import { Pool } from "pg";

// Only the connection pool is kept across hot reloads in development, so reloads don't open new connections.
// The PrismaClient itself is created fresh each time this module loads. Caching it as well made a client
// regenerated by `prisma generate` (new columns) invisible to a running dev server until it was restarted
// ("Unknown field ... for select statement on model ...").
const globalForPrisma = globalThis as unknown as {
  pool: Pool | undefined;
};

function createClient(): PrismaClient {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error("DATABASE_URL is required (PostgreSQL connection string).");
  }
  const pool =
    globalForPrisma.pool ??
    new Pool({
      connectionString: url,
      max: Number(process.env.PG_POOL_MAX ?? 10),
    });
  globalForPrisma.pool = pool;
  const adapter = new PrismaPg(pool);
  return new PrismaClient({ adapter });
}

export const prisma = createClient();
